1 2 2 3 3 4
3
4
5

//输出
3 4
5 5
-1 -1
```

```c++
#include<iostream>
using namespace std;
int a[100010];
int n=0,m=0;

int main(){
        scanf("%d%d",&n,&m);
        for(int i=0; i<n; i++) scanf("%d",&a[i]);
        while(m--){
                int x;
                scanf("%d", &x);

                int l=0, r=n-1;
                //找左边界
                while(l<r){
                        int mid = ((r-l)>>1)+l;
                        if (a[mid] >= x) r=mid;
                        else l=mid+1;
                }
                if (a[l] != x) cout<<"-1 -1"<<endl;
                else{
                        cout <<l <<' ';

                        int l =0, r=n-1;

                        //找右边界
                        while(l<r){
                                int mid = ((r-l+1)>>1)+l;
                                if (a[mid] <=x) l=mid;
                                else r=mid-1;
                        }
                        cout<<l<<endl;
                }
        }
        return 0;
}
