```c++
#include<iostream>
#include<vector>


using namespace std;

vector<int> A,B;

vector<int> add(vector<int> &A, vector<int> &B){
	vector<int> C;
	int t=0; //进位
	for(int i=0;i<A.size() || i<B.size();i++) {
		if(i<A.size()) t+=A[i];
		if(i<B.size()) t+=B[i];
