#include<iostream>
#include<vector> 
using namespace std;

vector<int> mul(vector<int> &A, int b){
	vector<int> C;

	for(int i=0 , t=0; i<A.size() || t; i++){ //t是进位
		if(i<A.size()) t += A[i]*b; //A[i]存在 
		C.push_back(t % 10);
		t /= 10;
	} 

    while (C.size() > 1 && C.back() == 0) C.pop_back();//前导零
	return C;
}

