/*
顺序表
静态分配
*/
#include<stdio.h>
#define MaxSize 10
typedef struct
{
    int data[MaxSize];
    int length;
}SqList;
//初始化
void InitList(SqList* L){
    L->length=0;//逻辑上置零
}
void PrintList(SqList L){
    //判空
    if(L.data==NULL || L.length==0)
        return;
    int i=0;
    for(i=0;i<L.length;i++)
        printf("%d ",L.data[i]);
}

int main(){
    SqList L;
    InitList(&L);
    ListInsert(&L,1,1);
    ListInsert(&L,2,2);
    ListInsert(&L,3,4);
    ListInsert(&L,4,5);
    printf("前：");
    PrintList(L);
    ListInsert(&L,3,3);
    printf("\n位序：3，插入：3");
    printf("\n后：");
    PrintList(L);

    //删除
    int x=0;
    ListDelete(&L,1,&x);
    printf("\n删除第%d个元素：%d",1,x);
    printf("\n删除后：");
    PrintList(L);

    ListDelete(&L,2,&x);
    printf("\n删除第%d个元素：%d",2,x);
    printf("\n删除后：");
    PrintList(L);

    printf("\n删除第%d个元素：%d",L.length,x);
    ListDelete(&L,L.length,&x);
    printf("\n删除后：");
    PrintList(L);

    //按位查找
    printf("\n第1个：%d",GetElement(L,0));
    printf("\n第2个：%d",GetElement(L,1));

    //按值查找
    printf("\n2的位序：%d",LocateElement(L,2));
    printf("\n4的位序：：%d",LocateElement(L,4));
    printf("\n5的位序：：%d",LocateElement(L,5));
    return 0;
}

//位序插入
int ListInsert(SqList *L,int i, int e){
    //满否
    if (L->length>=MaxSize || i<1 || i>L->length+1) return 0;
    int j=0;
    for(j=L->length;j>=i;j--)//后移
        L->data[j]=L->data[j-1];
    L->data[j]=e;//插入
    return ++(L->length);
}

//删除
int ListDelete(SqList *L,int i, int *e){
    if(i<1|| i>L->length) return 0;
    *e=L->data[i-1];
    int j=i;
    for(;j<L->length;j++) L->data[j-1]=L->data[j];
    L->length--;
    return 1;
}

//按位查找
int GetElement(SqList L,int i){
    if(i<1 || i>L.length) return 0;
    return L.data[i-1];
}

//按值查找
int LocateElement(SqList L,int e){
    int i=0;
    for(;i<L.length;i++)
        if(L.data[i]==e)
            return i+1;
    return -1;
}
