```c
#include<stdio.h>
#include<stdlib.h>
typedef struct LNode{
    int data;
    struct LNode *next;
} LNode, *Linklist;
//输出链表
void printlist(LNode L){
    LNode* p=&L;
    for(;p!=NULL;p=p->next)
        printf("%d ",p->data);
}

//头插法-带头结点
Linklist HeadInsert(Linklist L){
    LNode *s;
    int i=0,x=0;
    int input[6]={5,4,3,2,1,-1};
    L=(Linklist)malloc(sizeof(LNode));
    L->next=NULL;
    for(;input[i]!=-1;i++){
        InsertNextNode(L,input[i]);
    }
    return L;
}

//尾插法-带头结点
Linklist TailInsert(Linklist L){
    LNode *s,*r;
    int i=0,x=0;
    int input[6]={5,4,3,2,1,-1};
    L=(Linklist)malloc(sizeof(LNode));
    L->next=NULL;
    r=L;
    for(;input[i]!=-1;i++){
        s=(LNode*)malloc(sizeof(LNode));
        s->data=input[i];
        r->next=s;
        r=s;
    }
    r->next=NULL;
    return L;
}

//尾插法-不带头结点
Linklist HeadInsertNoHead(Linklist L){
    LNode *s;
    int i=1,x=0;
    int input[6]={5,4,3,2,1,-1};
    L=(Linklist)malloc(sizeof(LNode));
    L->data=input[0];
    L->next=NULL;
    for(;input[i]!=-1;i++){
        s=(LNode*)malloc(sizeof(LNode));
        s->next=L->next;
        L->next=s;
        s->data=input[i];
    }
    return L;
}



//按位查找
LNode* GetElement(Linklist L,int i){
    if(i<0) return NULL;
    int j=0;
    LNode* p=L;
    for(;p!=NULL && j<i;j++)
        p=p->next;
    return p;
}

//按值查找
LNode* LocateElem(Linklist L,int e){
    LNode* p=L->next;
    for(;p!=NULL && p->data!=e;p=p->next);
    return p;
}

//求
int Length(Linklist L){
    int i=0;
    LNode* p=L;
    for(;p!=NULL;p=p->next)
        i++;
    return i;
}

void test_head(){
    printf("带头结点测试：");
    Linklist L=NULL;
    L=HeadInsert(L);
    printlist(*(L->next));

    //按位查找
    printf("\n第3个位置的元素为：%d\n",GetElement(L,3)->data);

    //按位插入
    printf("\n在第1个位置插入11\n");
    ListInsert_head(L,1,11);
    printf("插入后：");
    printlist(*(L->next));    

    //后插
    printf("\n在第2个位置后插22\n");
    LNode *p=GetElement(L,2);
    InsertNextNode(p,22);
    printf("插入后：");
    printlist(*(L->next));

    //前插
    printf("\n在第3个位置前插33\n");
    p=GetElement(L,3);
    InsertPriorNode(p,33);
    printf("插入后：");
