//按位插入_不头
int ListInsert_nohead(Linklist *L,int i, int e){
    if(i<1) return 0;
    if(i==1){
        LNode *s=(LNode*)malloc(sizeof(LNode));
        s->data=e;
        s->next=*L;
        *L=s;
        return 1;
    }
    LNode *p=*L;
    int j=1;
    for(;p!=NULL && j<i-1;j++) p=p->next;
    if(p==NULL) return 0;
    LNode *s=(LNode*)malloc(sizeof(LNode));
    s->data=e;
    s->next=p->next;//顺序不能换        
    p->next=s;
    return 1;
}

//后插
int InsertNextNode(LNode *p, int e){
    if(p==NULL) return 0;
    LNode *s=(LNode*)malloc(sizeof(LNode));
    s->data=e;
    s->next=p->next;
    p->next=s;
    return 1;
}

//前插
int InsertPriorNode(LNode *p, int e){//只需交换数据域
    if(p==NULL) return 0;
    LNode *s=(LNode*)malloc(sizeof(LNode));
    if(s==NULL) return 0;
    s->next=p->next;
    p->next=s;
    s->data=p->data;
    p->data=e;
    return 1;
}

//按位删除
int ListDelete(Linklist L, int i, int *e){
    if(i<1) return 0;
    LNode *p=L;
    int j=0;
    for(;p!=NULL && j<i-1;j++) p=p->next;
    if(p==NULL) return 0;
    LNode *q=p->next;
    if(q==NULL) return 0;
    p->next=q->next;
    *e=q->data;
    free(q);
    return 1;
}

//逆置
void Reverse(Linklist *L){
    LNode *p=(*L)->next;
    (*L)->next=NULL;
    LNode *q;
    while(p!=NULL){
        q=p->next;
        p->next=(*L)->next;
        (*L)->next=p;
        p=q;
    }
}
