```c
#include<stdio.h>
#define MAXSIZE 10
typedef struct{
    char data[MAXSIZE];
    int top;
} SqStack;

//初始化
void InitStack(SqStack *S){
    S->top=-1;
}

//判空
int StackEmpty(SqStack S){
    if(S.top==-1)
        return 1;
    else
        return 0;
}

//入栈
int Push(SqStack *S, char x){
    if(S->top==MAXSIZE-1)
        return 0;
    S->top++;
    S->data[S->top]=x;
    return 1;
}

//出栈
int Pop(SqStack *S, char *x){
    if(S->top==-1)
        return 0;
    *x=S->data[S->top];
    S->top--;
    return 1;
}

//取栈顶元素
int GetTop(SqStack S, char *x){
    if(S.top==-1)
        return 0;
    *x=S.data[S.top];
    return 1;
}

int main(){
    //1. 括号匹配
    char str1[100] = "((())){[]}"; //合法
    char str2[100] = "((()){[]})"; //合法
    char str3[100] = "((()){[]}"; //不合法
    printf("%d",match(str1));
    printf("%d",match(str2));
    printf("%d",match(str3));
}

int match(char str[]){
    SqStack stack;
    InitStack(&stack);
    int i=0;
    char x;
    for(;str[i]!='\0';i++){
        switch (str[i])
        {
        case '(':
        case '[':
        case '{':
            Push(&stack, str[i]);
            break;
        case ')':
            if(!Pop(&stack, &x) || x!='(')
                return 0;
            break;
        case ']':
            if(!Pop(&stack, &x) || x!='[')
                return 0;
            break;
        case '}':
            if(!Pop(&stack, &x) || x!='{')
                return 0;
            break;
        default:
            break;
        }
    }
    if(!StackEmpty(stack))
        return 0;
    return 1;
}
