```c
//中序线索化
ThreadNode *pre=NULL;
void InThread(ThreadTree p){
    if(p){
        InThread(p->lchild);
        if(!p->lchild){
            p->lchild=pre;
            p->ltag=1;
        }
        if(!pre->rchild){
            pre->rchild=p;
            pre->rtag=1;
        }
        pre=p;
        InThread(p->rchild);
    }
}
//先序线索化
void PreThread(ThreadTree p){
    if(p){
        if(!p->lchild){
            p->lchild=pre;
            p->ltag=1;
        }
        if(!pre->rchild){
            pre->rchild=p;
            pre->rtag=1;
        }
        pre=p;
        if(p->ltag==0)
            PreThread(p->lchild);
        PreThread(p->rchild);
    }
}
//后序线索化
void PostThread(ThreadTree p){
    if(p){
        if(!p->lchild){
            p->lchild=pre;
            p->ltag=1;
        }
        if(!pre->rchild){
            pre->rchild=p;
            pre->rtag=1;
        }
        pre=p;
        PreThread(p->lchild);
        PreThread(p->rchild);
    }
}
void CreateInThread(ThreadTree T){
    pre=NULL;
    if(T){
        InThread(T);
        if(!pre->rchild){
            pre->rtag=1;
        }
    }
}
```

- 线索二叉树找前驱/后继
![](../../../../theme/yilia/source/img/datastruct/5_tree/bintree/22.png)
![数据结构](https://cdn.jsdelivr.net/gh/lankeren035/lankeren035.github.io@source/themes/yilia/source/img/datastruct/5_tree/bintree/22.png)
    - 中序，后继

        1）p->rtag==1，则next=p->rchild

        2）p->rtag==0，则
        ```c
        //中序线索二叉树找后继
        ThreadNode *Firstnode(ThreadNode *p){
            while(p->ltag==0)
                p=p->lchild;
            return p;
        }
        ThreadNode *Nextnode(ThreadNode *p){
            if(p->rtag==0)
                return Firstnode(p->rchild);
            else
                return p->rchild;
        }
        ```
    - 中序，前驱

        1）p->ltag==1，则pre=p->lchild

        2）p->ltag==0,pre=左子树的最右下

        ```c
        //中序线索二叉树找到前驱
        ThreadNode *Lastnode(ThreadNode *p){
            while(p->rtag==0)
                p=p->rchild;
            return p;
        }
        ThreadNode *Prenode(ThreadNode *p){
            if(p->ltag==0)
                return Lastnode(p->lchild);
            else
                return p->lchild;
        }
        //对中序线索二叉树逆向遍历
        void InOrder(ThreadNode *T){
            for(ThreadNode *p=Lastnode(T); p!=NULL; p=Prenode(p))
                visit(p);
        }
        ```
    - 先序，后继

        1）p->rtag==1，则next=p->rchild

        2）p->rtag==0，则next=左孩子（无则右孩子）

    - 先序，前驱


        1）p->ltag==1，则prep->lchild

        2）p->ltag==0

        - 若能找到p的父，p为左孩子，则pre=父

        - 若能找到p的父，p为右孩子，左兄弟空，则pre=父

        - 若能找到p的父，p为右孩子，左兄弟不空，则pre=左子树中最后一个被中序遍历的结点

    - 后序，前驱

        1）p->ltag==1，则pre=p->lchild

        2）p->ltag==0，则pre=右孩子（无则左孩子）

    - 后序，后继


        1）p->rtag==1，则next->rchild

        2）p->rtag==0

        - 若能找到p的父，p为右孩子，则next=父

        - 若能找到p的父，p为左孩子，右兄弟空，则next=父

        - 若能找到p的父，p为左孩子，右兄弟不空，则next=右子树中第一个被后序遍历的结点

