- 求树的深度
```c
//求树的深度
int treeDepth(BiTree T){
    if(!T)
        return 0;
    else{
        int l=treeDepth(T->lchild);
        int r=treeDepth(T->rchild);
        return (l>r)?(l+1):(r+1);
    }
}
```

- 层次遍历
```c
//层次遍历
void LevelOrder(BiTree T){
    BiTree p;
    BiTree q[MaxSize];
    int front=0, rear=0;
    if(T){
        rear=(rear+1)%MaxSize;
        q[rear]=T;
        while(front!=rear){
            front=(front+1)%MaxSize;
            p=q[front];
            visit(p);
            if(p->lchild){
                rear=(rear+1)%MaxSize;
                q[rear]=p->lchild;
            }
            if(p->rchild){
                rear=(rear+1)%MaxSize;
                q[rear]=p->rchild;
            }
        }
    }
}
```

