        def dfs(i, c):
            if i< 0:
                return 0 if c==0 else inf
            if coins[i] > c:
                return dfs(i-1 , c)
            return min(dfs(i-1, c) , dfs(i, c - coins[i]) + 1)
        def dp1():
            dp_map = [[inf] * (amount + 1) for _ in range( n+ 1 )]
            dp_map[0][0] = 0
            for i in range(n):
